import React from 'react';
import './ExcursionCard.css';
import { Link } from 'react-router-dom';


const ExcursionCard = ({
  excursion,
  isFavorite,
  inCart,
  onToggleFavorite,
  onToggleCart
}) => {
  return (
    <Link to={`/tour/${excursion.id}`} className="excursion-card__link">
    <div className="excursion-card">
      <div className="excursion-card__image-wrapper">
        <img
          src={excursion.image}
          alt={excursion.title}
          className="excursion-card__image"
        />

        {/* ИЗБРАННОЕ */}
        <button
          className="excursion-card__favorite"
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            onToggleFavorite(excursion.id);
          }}
          title={
            isFavorite
              ? 'Удалить из избранного'
              : 'Добавить в избранное'
          }
        >
          <img
            src={
              isFavorite
                ? '/assets/icons/heart2.svg'
                : '/assets/icons/like.svg'
            }
            alt="Избранное"
          />
        </button>
      </div>

      <div className="excursion-card__body">
        <h3 className="excursion-card__title">
          {excursion.title}
        </h3>

        <p className="excursion-card__location">
          {excursion.country}, {excursion.city}
        </p>

        <div className="excursion-card__info">
          <span className="excursion-card__price">
            {excursion.price.toLocaleString()} ₽
          </span>

          <span className="excursion-card__rating">
            ★ {excursion.rating}
          </span>
        </div>

        <button
          className={`excursion-card__button ${
            inCart ? 'excursion-card__button--added' : ''
          }`}
          onClick={() => onToggleCart(excursion.id)}
        >
          {inCart ? 'Убрать из корзины' : 'В корзину'}
        </button>
      </div>
    </div>
    </Link>
  );
};

export default ExcursionCard;
